-- name: v2
SELECT pre, doe_before, ted_before, seq1, fold_seq_row, fold_seqless, COUNT(*) AS versions, COUNT(DISTINCT tid) AS tenders, MIN(nid) AS nid_lo, MAX(nid) AS nid_hi, MIN(ing) AS ing_lo, MAX(ing) AS ing_hi FROM (SELECT n.id AS nid, n.ingested_at AS ing, v.tender_id AS tid, v.seq = 1 AS seq1, t.created_at < n.ingested_at AS pre, EXISTS (SELECT 1 FROM tender_versions v2 CROSS JOIN notices n2 ON n2.id = v2.caused_by_notice_id WHERE v2.tender_id = v.tender_id AND n2.id < n.id AND +n2.source = 'doe') AS doe_before, EXISTS (SELECT 1 FROM tender_versions v2 CROSS JOIN notices n2 ON n2.id = v2.caused_by_notice_id WHERE v2.tender_id = v.tender_id AND n2.id < n.id AND +n2.source = 'ted') AS ted_before, EXISTS (SELECT 1 FROM changes c WHERE c.entity_kind = 'tender' AND c.entity_id = v.tender_id AND c.version_seq = v.seq AND c.changed_at = 1792482087 AND c.cursor > 958853608 AND c.cursor <= 958904203) AS fold_seq_row, EXISTS (SELECT 1 FROM changes c WHERE c.entity_kind = 'tender' AND c.entity_id = v.tender_id AND c.version_seq IS NULL AND +c.op = 'changed' AND c.changed_at = 1792482087 AND c.cursor > 958853608 AND c.cursor <= 958904203) AS fold_seqless FROM notices n CROSS JOIN tender_versions v ON v.caused_by_notice_id = n.id CROSS JOIN tenders t ON t.id = v.tender_id WHERE n.id > 47414700 AND n.id <= 47419700 AND +n.source = 'ted' AND n.ingested_at >= 1792454400 AND n.ingested_at < 1792540800) AS w GROUP BY pre, doe_before, ted_before, seq1, fold_seq_row, fold_seqless ORDER BY 1, 2, 3, 4, 5, 6 LIMIT 100
